/**
 * Postmark inbound email JSON payload.
 */
export type MarketplaceEmailInboundBodyOne = {
  /** Unique message ID for deduplication. */
  MessageID?: string;
  From?: string;
  /** Recipient address. Must contain the workspace owner ID using the plus-addressing format: `marketplace-reports+{workspaceOwnerId}@<domain>`.
   */
  To?: string;
  ToFull?: MarketplaceEmailInboundBodyOneToFullItem[];
  Subject?: string;
  Attachments?: MarketplaceEmailInboundBodyOneAttachmentsItem[];
  /** Explicit workspace owner ID. Takes precedence over the To-address parsing if provided.
   */
  workspace_owner_id?: string;
};

/**
 * Mailgun or SendGrid inbound parse multipart payload. PDF files are sent as file upload fields. Mailgun uses `attachment-1`, `attachment-2`, … field names and a `recipient` text field. SendGrid uses `attachment1`, `attachment2`, … field names and an `envelope` JSON text field.

 */
export type MarketplaceEmailInboundBodyTwo = {
  /** (Mailgun) Comma-separated recipient To addresses. Must contain `marketplace-reports+{workspaceOwnerId}@<domain>`.
   */
  recipient?: string;
  /** (Mailgun alternative) To address field.
   */
  to?: string;
  /** (Mailgun) RFC Message-ID for deduplication. */
  'Message-Id'?: string;
  /** (SendGrid) JSON string with shape `{ "to": ["addr"], "from": "addr" }`. The `to` array must contain `marketplace-reports+{workspaceOwnerId}@<domain>`.
   */
  envelope?: string;
  /** (SendGrid) Raw email headers string; used to extract Message-ID. */
  headers?: string;
  /** Email subject line. */
  subject?: string;
  /** (Mailgun) First PDF attachment. */
  'attachment-1'?: Blob;
  /** (Mailgun) Second PDF attachment. */
  'attachment-2'?: Blob;
  /** (SendGrid) First PDF attachment. */
  attachment1?: Blob;
  /** (SendGrid) Second PDF attachment. */
  attachment2?: Blob;
};

